#include <stdio.h>

int main(void) {
    char g[10][10];
    for (int i = 0; i < 10; i++)
        for (int j = 0; j < 10; j++)
            scanf(" %c", &g[i][j]);

    int regions = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (g[i][j] != '#') continue;
            regions++;
            int sx[100], sy[100], sp = 0;
            sx[sp] = i;
            sy[sp] = j;
            sp++;
            g[i][j] = '.';
            while (sp > 0) {
                sp--;
                int x = sx[sp];
                int y = sy[sp];
                int dx[4] = {1, -1, 0, 0};
                int dy[4] = {0, 0, 1, -1};
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx < 0 || nx >= 10 || ny < 0 || ny >= 10) continue;
                    if (g[nx][ny] != '#') continue;
                    g[nx][ny] = '.';
                    sx[sp] = nx;
                    sy[sp] = ny;
                    sp++;
                }
            }
        }
    }

    printf("%d\n", regions);
    return 0;
