#include <stdio.h>

#define MAX_LIMIT 1000000

static char is_composite[MAX_LIMIT + 1];

static int read_limit(void)
{
    int limit;

    if (scanf("%d", &limit) != 1)
        return -1;
    if (limit < 0 || limit > MAX_LIMIT)
        return -1;
    return limit;
}

static void sieve_up_to(int limit)
{
    for (int candidate = 2; candidate * candidate <= limit; ++candidate) {
        if (!is_composite[candidate]) {
            for (int multiple = candidate * candidate;
                 multiple <= limit;
                 multiple += candidate) {
                is_composite[multiple] = 1;
            }
        }
    }
}

static void print_primes_up_to(int limit)
{
    for (int number = 2; number <= limit; ++number) {
        if (!is_composite[number])
            printf("%d\n", number);
    }
}

int main(void)
{
    int limit = read_limit();

    if (limit < 2)
        return 0;

    sieve_up_to(limit);
    print_primes_up_to(limit);
    return 0;
}
