#include <stdio.h>
#include <stdlib.h>

static void selection_sort(int *values, size_t count) {
    for (size_t i = 0; i + 1 < count; ++i) {
        size_t smallest_index = i;
        for (size_t j = i + 1; j < count; ++j) {
            if (values[j] < values[smallest_index]) {
                smallest_index = j;
            }
        }
        if (smallest_index != i) {
            int temporary = values[i];
            values[i] = values[smallest_index];
            values[smallest_index] = temporary;
        }
    }
}

static int read_values(int **values, size_t *count) {
    int number_count;

    if (scanf("%d", &number_count) != 1 || number_count < 0) {
        return 0;
    }

    *count = (size_t)number_count;

    if (number_count == 0) {
        *values = NULL;
        return 1;
    }

    *values = malloc((size_t)number_count * sizeof **values);
    if (*values == NULL) {
        return 0;
    }

    for (int i = 0; i < number_count; ++i) {
        if (scanf("%d", &(*values)[i]) != 1) {
            free(*values);
            *values = NULL;
            return 0;
        }
    }

    return 1;
}

static void print_values(const int *values, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');
}

int main(void) {
    int *values = NULL;
    size_t count = 0;

    if (!read_values(&values, &count)) {
        return EXIT_FAILURE;
    }

    selection_sort(values, count);
    print_values(values, count);

    free(values);
    return EXIT_SUCCESS;
}
