#include <stdio.h>

struct Complex {
    double re;
    double im;
};

static struct Complex read_complex(void)
{
    struct Complex value;

    if (scanf("%lf %lf", &value.re, &value.im) != 2) {
        value.re = 0.0;
        value.im = 0.0;
    }

    return value;
}

static struct Complex multiply_complex(struct Complex left, struct Complex right)
{
    struct Complex result;

    result.re = left.re * right.re - left.im * right.im;
    result.im = left.re * right.im + left.im * right.re;

    return result;
}

static void print_complex(struct Complex value)
{
    printf("%.6f %.6f\n", value.re, value.im);
}

int main(void)
{
    struct Complex first = read_complex();
    struct Complex second = read_complex();
    struct Complex product = multiply_complex(first, second);

    print_complex(product);
    return 0;
}
