#include <stdio.h>

int main(void) {
    int counts[256] = {0};
    int total = 0;
    int c;

    while ((c = getchar()) != EOF) {
        if (c == '\n') {
            continue;
        }
        counts[(unsigned char)c]++;
        total++;
    }

    if (total == 0) {
        putchar('\n');
        return 0;
    }

    int best = 0;
    for (int i = 1; i < 256; i++) {
        if (counts[i] > counts[best]) {
            best = i;
        }
    }

    printf("%c %d\n", best, counts[best]);
    return 0;
}
